from datetime import date, timedelta

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # Store used days per employee per year
        self.used: dict[str, dict[int, int]] = {}

    def _count_leave_days(self, start: date, end: date) -> int:
        count = 0
        current = start
        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                count += 1
            current += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date cannot be before start date.")
        if (start - today).days < 3:
            raise ValueError("Leave requests must be made at least 3 days in advance.")

        days_requested = self._count_leave_days(start, end)

        # A request spanning multiple years: count per year separately
        # Determine years involved
        year_used = {}
        current = start
        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                year_used[current.year] = year_used.get(current.year, 0) + 1
            current += timedelta(days=1)

        # Check remaining for each year involved
        for year, days in year_used.items():
            if days > self.remaining(employee, year):
                raise ValueError(
                    f"Insufficient leave days remaining for {year}: "
                    f"requested {days}, available {self.remaining(employee, year)}."
                )

        # Deduct
        emp_used = self.used.setdefault(employee, {})
        for year, days in year_used.items():
            emp_used[year] = emp_used.get(year, 0) + days

        return days_requested

    def remaining(self, employee: str, year: int) -> int:
        used = self.used.get(employee, {}).get(year, 0)
        return self.days_per_year - used
